package org.efootballrevival.runtimeprobe;
import android.app.*;import android.content.*;import android.widget.*;import android.text.InputType;import org.json.*;import java.util.*;
public final class TuningEditor{
 private static String manage(Activity a,String action,JSONObject req)throws Exception{return(String)Class.forName("org.efootballrevival.runtimeprobe.EmbeddedGateway").getMethod("manage",Context.class,String.class,String.class).invoke(null,a,action,req.toString());}
 private static void error(Activity a,Exception e){if(!a.isFinishing())new AlertDialog.Builder(a).setTitle("Player Editor").setMessage(String.valueOf(e.getCause()==null?e.getMessage():e.getCause().getMessage())).setPositiveButton("Close",null).show();}
 private static void attach(Activity a,LinearLayout panel,JSONObject player,boolean skills){Button b=new Button(a);b.setText(skills?"Edit Innate Skills":"Physics · Verified Inputs");b.setAllCaps(false);b.setOnClickListener(v->{b.setEnabled(false);new Thread(()->{try{JSONObject data=new JSONObject(manage(a,skills?"ui77_skills_get":"ui77_physics_get",player));a.runOnUiThread(()->{b.setEnabled(true);if(!a.isFinishing()){if(skills)skills(a,player,data);else physics(a,player,data);}});}catch(Exception e){a.runOnUiThread(()->{b.setEnabled(true);error(a,e);});}},"PlayerTuningLoad").start();});panel.addView(b,new LinearLayout.LayoutParams(-1,-2));}
 public static void attachSkills(Activity a,LinearLayout panel,JSONObject player){attach(a,panel,player,true);}public static void attachPhysics(Activity a,LinearLayout panel,JSONObject player){attach(a,panel,player,false);}
 private static void save(Activity a,AlertDialog d,String action,JSONObject req){d.getButton(-1).setEnabled(false);new Thread(()->{try{JSONObject reply=new JSONObject(manage(a,action,req));if(!reply.optBoolean("saved",false))throw new Exception("Save was not confirmed");a.runOnUiThread(()->{d.dismiss();Toast.makeText(a,"Saved. Reopen player details to refresh.",Toast.LENGTH_LONG).show();});}catch(Exception e){a.runOnUiThread(()->{d.getButton(-1).setEnabled(true);error(a,e);});}},"PlayerTuningSave").start();}
 private static void skills(Activity a,JSONObject player,JSONObject data){JSONArray choices=data.optJSONArray("choices"),selected=data.optJSONArray("selected");if(choices==null)return;int n=choices.length();String[] names=new String[n];int[] ids=new int[n];boolean[] checked=new boolean[n];HashSet<Integer> before=new HashSet<>();if(selected!=null)for(int i=0;i<selected.length();i++)before.add(selected.optInt(i));for(int i=0;i<n;i++){JSONObject row=choices.optJSONObject(i);ids[i]=row.optInt("id");checked[i]=before.contains(ids[i]);names[i]=row.optString("label")+(checked[i]?" · Current":"");}AlertDialog d=new AlertDialog.Builder(a).setTitle("Innate Skills · "+before.size()+" current").setMultiChoiceItems(names,checked,(dialog,i,on)->checked[i]=on).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();d.show();ResponsiveUi.fit(a,d);d.getButton(-1).setOnClickListener(v->{try{JSONArray out=new JSONArray();for(int i=0;i<n;i++)if(checked[i])out.put(ids[i]);JSONObject req=new JSONObject(player.toString()).put("selected",out);save(a,d,"ui77_skills_apply",req);}catch(Exception e){error(a,e);}});}
 private static EditText field(Activity a,LinearLayout panel,String label,int value){TextView t=new TextView(a);t.setText(label);t.setTextColor(0xffe6f3ff);panel.addView(t);EditText e=new EditText(a);e.setText(String.valueOf(value));e.setInputType(InputType.TYPE_CLASS_NUMBER);e.setSingleLine(true);e.setTextColor(0xfff5fbff);panel.addView(e,new LinearLayout.LayoutParams(-1,-2));return e;}
 private static void physics(Activity a,JSONObject player,JSONObject data){LinearLayout col=new LinearLayout(a);col.setOrientation(1);col.setPadding(24,16,24,16);col.setBackgroundColor(0xff101f38);ScrollView scroll=new ScrollView(a);scroll.addView(col);TextView note=new TextView(a);note.setText("Reach, jumping height and collision metrics depend on body proportions and attributes. These controls edit verified game inputs; they are not independent EFHub physics overrides. Height above255cm cannot fit the native field. Rendering may clamp extreme dimensions.");note.setTextColor(0xffc9dfee);col.addView(note);EditText h=field(a,col,"Height · 140–255 cm",data.optInt("height",180)),w=field(a,col,"Weight · 40–250 kg",data.optInt("weight",75)),j=field(a,col,"Jump attribute · 40–99",data.optInt("jump",70));PlayerModelEditor.attach(a,col,player);AlertDialog d=new AlertDialog.Builder(a).setTitle("Physics · Verified Inputs").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();d.show();ResponsiveUi.fit(a,d);d.getButton(-1).setOnClickListener(v->{try{JSONObject req=new JSONObject(player.toString()).put("height",Integer.parseInt(h.getText().toString().trim())).put("weight",Integer.parseInt(w.getText().toString().trim())).put("jump",Integer.parseInt(j.getText().toString().trim()));save(a,d,"ui77_physics_apply",req);}catch(Exception e){error(a,e);}});}
}
